// GESTIÓN DE ACCIONES Y PERMISOS ATÓMICOS
// ==========================================

function poblarSelectoresModulosRBAC() {
    const selModal = document.getElementById('modalPermisoModuloId');
    const selFiltro = document.getElementById('filtroModuloPermisosCat');

    const modulos = cacheRBAC.modulosCat && cacheRBAC.modulosCat.length > 0 ? cacheRBAC.modulosCat : (cacheRBAC.modulos || []);

    if (selModal) {
        const valActual = selModal.value;
        selModal.innerHTML = '<option value="">-- Seleccionar Módulo --</option>' +
            modulos.map(m => {
                const id = m.id || m.Id || m.moduloId || m.ModuloId;
                const nom = m.nombre || m.Nombre;
                const cod = m.codigo || m.Codigo;
                return `<option value="${id}">${nom} (${cod})</option>`;
            }).join('');
        if (valActual) selModal.value = valActual;
    }

    if (selFiltro) {
        const valActual = selFiltro.value;
        selFiltro.innerHTML = '<option value="">Todos los Módulos</option>' +
            modulos.map(m => {
                const id = m.id || m.Id || m.moduloId || m.ModuloId;
                const nom = m.nombre || m.Nombre;
                return `<option value="${id}">${nom}</option>`;
            }).join('');
        if (valActual) selFiltro.value = valActual;
    }
}

async function cargarPermisosCat() {
    try {
        const modId = document.getElementById('filtroModuloPermisosCat')?.value || '';
        const tipoAcc = document.getElementById('filtroTipoAccionPermisosCat')?.value || '';

        let params = [];
        if (modId) params.push(`moduloId=${modId}`);
        if (tipoAcc) params.push(`accion=${encodeURIComponent(tipoAcc)}`);

        const qs = params.length > 0 ? `?${params.join('&')}` : '';
        const resp = await fetch(`/api/permisos${qs}`, {
            headers: getAuthHeaders()
        });
        if (resp.ok) {
            cacheRBAC.permisos = await resp.json();
            renderTablaPermisosCat(cacheRBAC.permisos || []);
        }
    } catch (e) {
        console.error('Error al cargar catálogo de permisos:', e);
    }
}
window.cargarPermisosCat = cargarPermisosCat;

function filtrarPermisosCat(query) {
    cacheRBAC.filtroPermisos = (query || '').toLowerCase().trim();
    const filtrados = (cacheRBAC.permisos || []).filter(p => {
        const cod = (p.codigo || p.Codigo || '').toLowerCase();
        const nom = (p.nombre || p.Nombre || '').toLowerCase();
        const desc = (p.descripcion || p.Descripcion || '').toLowerCase();
        const mod = (p.moduloNombre || p.ModuloNombre || '').toLowerCase();
        return cod.includes(cacheRBAC.filtroPermisos) || nom.includes(cacheRBAC.filtroPermisos) || desc.includes(cacheRBAC.filtroPermisos) || mod.includes(cacheRBAC.filtroPermisos);
    });
    renderTablaPermisosCat(filtrados);
}
window.filtrarPermisosCat = filtrarPermisosCat;

function renderTablaPermisosCat(lista) {
    const tbody = document.getElementById('tbodyPermisosCat');
    const badgeTotal = document.getElementById('badgeTotalPermisosCat');
    if (!tbody) return;

    if (badgeTotal) badgeTotal.textContent = `${lista.length} Acciones`;

    if (!lista || lista.length === 0) {
        tbody.innerHTML = `<tr><td colspan="9" class="text-center" style="padding: 30px; color: #64748b; font-weight: 600;">No se encontraron acciones o permisos con el criterio seleccionado.</td></tr>`;
        return;
    }

    let html = '';
    lista.forEach(p => {
        const pId = Number(p.id || p.Id || p.permisoId || p.PermisoId);
        const pMod = p.moduloNombre || p.ModuloNombre || 'Sin Módulo';
        const pCod = p.codigo || p.Codigo || '';
        const pAcc = (p.accion || p.Accion || 'VER').toUpperCase();
        const pNom = p.nombre || p.Nombre || '';
        const pDesc = p.descripcion || p.Descripcion || '-';
        const pRoles = p.totalRolesAsignados !== undefined ? p.totalRolesAsignados : (p.TotalRolesAsignados !== undefined ? p.TotalRolesAsignados : 0);
        const pAct = p.activo !== undefined ? p.activo : (p.Activo !== undefined ? p.Activo : true);

        // Badge color por acción
        let badgeBg = '#eff6ff';
        let badgeColor = '#1d4ed8';
        let badgeBorder = '#bfdbfe';
        if (pAcc === 'CREAR') { badgeBg = '#ecfdf5'; badgeColor = '#047857'; badgeBorder = '#a7f3d0'; }
        else if (pAcc === 'EDITAR') { badgeBg = '#fffbeb'; badgeColor = '#b45309'; badgeBorder = '#fde68a'; }
        else if (pAcc === 'ELIMINAR') { badgeBg = '#fef2f2'; badgeColor = '#b91c1c'; badgeBorder = '#fecaca'; }
        else if (pAcc === 'APROBAR') { badgeBg = '#faf5ff'; badgeColor = '#7e22ce'; badgeBorder = '#e9d5ff'; }
        else if (pAcc === 'EXPORTAR') { badgeBg = '#f0fdfa'; badgeColor = '#0f766e'; badgeBorder = '#99f6e4'; }

        html += `
            <tr style="border-bottom: 1px solid #f1f5f9; transition: background 0.15s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='transparent'">
                <td style="font-weight: 800; color: #64748b; padding: 12px 14px;">#${pId}</td>
                <td style="font-weight: 800; color: #334155; padding: 12px 14px;">${pMod}</td>
                <td style="padding: 12px 14px;"><span style="font-family: monospace; font-weight: 800; color: #1d4ed8; background: #eff6ff; border: 1px solid #bfdbfe; padding: 3px 8px; border-radius: 6px;">${pCod}</span></td>
                <td style="text-align: center; padding: 12px 14px;">
                    <span style="font-size: 11px; font-weight: 800; padding: 3px 8px; border-radius: 6px; background: ${badgeBg}; color: ${badgeColor}; border: 1px solid ${badgeBorder};">
                        ${pAcc}
                    </span>
                </td>
                <td style="font-weight: 800; color: #0f172a; padding: 12px 14px;">${pNom}</td>
                <td style="font-size: 12.5px; color: #64748b; max-width: 260px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 12px 14px;" title="${pDesc}">${pDesc}</td>
                <td style="text-align: center; padding: 12px 14px;">
                    <span style="font-size: 11.5px; font-weight: 800; padding: 3px 8px; border-radius: 6px; ${pRoles > 0 ? 'background: #eff6ff; color: #1d4ed8; border: 1px solid #bfdbfe;' : 'background: #f1f5f9; color: #64748b; border: 1px solid #e2e8f0;'}">
                        ${pRoles} Roles
                    </span>
                </td>
                <td style="text-align: center; padding: 12px 14px;">
                    <span style="font-size: 11px; font-weight: 800; padding: 3px 8px; border-radius: 6px; ${pAct ? 'background: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;' : 'background: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;'}">
                        ${pAct ? 'Activo' : 'Inactivo'}
                    </span>
                </td>
                <td style="text-align: center; padding: 12px 14px;">
                    <div style="display: inline-flex; gap: 6px;">
                        <button type="button" onclick="abrirModalEditarPermiso(${pId})" title="Editar Permiso" 
                            style="padding: 5px 9px; font-size: 12px; border-radius: 6px; border: 1px solid #bfdbfe; background: #eff6ff; color: #2563eb; cursor: pointer; transition: all 0.15s ease;">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button type="button" onclick="eliminarPermisoRBAC(${pId}, '${pNom}')" title="Eliminar Permiso" 
                            style="padding: 5px 9px; font-size: 12px; border-radius: 6px; border: 1px solid #fecaca; background: #fef2f2; color: #dc2626; cursor: pointer; transition: all 0.15s ease;">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    });

    tbody.innerHTML = html;
}

function sugerirCodigoPermiso() {
    const isEdit = !!document.getElementById('modalPermisoId').value;
    if (isEdit) return; // No auto-cambiar en edición

    const modId = document.getElementById('modalPermisoModuloId').value;
    const accion = document.getElementById('modalPermisoAccion').value;
    const modObj = (cacheRBAC.modulosCat || cacheRBAC.modulos || []).find(m => Number(m.id || m.Id || m.moduloId || m.ModuloId) === Number(modId));
    
    if (modObj && accion) {
        const modCod = (modObj.codigo || modObj.Codigo || '').toUpperCase();
        const inputCod = document.getElementById('modalPermisoCodigo');
        const inputNom = document.getElementById('modalPermisoNombre');
        
        if (inputCod) inputCod.value = `${modCod}_${accion}`;
        
        // Sugerir nombre legible
        let verbo = 'Ver';
        if (accion === 'CREAR') verbo = 'Crear / Registrar';
        else if (accion === 'EDITAR') verbo = 'Editar / Modificar';
        else if (accion === 'ELIMINAR') verbo = 'Eliminar / Anular';
        else if (accion === 'APROBAR') verbo = 'Aprobar / Cerrar';
        else if (accion === 'EXPORTAR') verbo = 'Exportar Reportes de';

        if (inputNom && (!inputNom.value || inputNom.dataset.autoSugerido === 'true')) {
            inputNom.value = `${verbo} ${modObj.nombre || modObj.Nombre}`;
            inputNom.dataset.autoSugerido = 'true';
        }
    }
}
window.sugerirCodigoPermiso = sugerirCodigoPermiso;

function abrirModalCrearPermiso() {
    poblarSelectoresModulosRBAC();
    document.getElementById('modalPermisoTitle').textContent = 'Registrar Nueva Acción / Permiso';
    document.getElementById('modalPermisoId').value = '';
    document.getElementById('modalPermisoModuloId').value = '';
    document.getElementById('modalPermisoAccion').value = 'VER';
    document.getElementById('modalPermisoCodigo').value = '';
    document.getElementById('modalPermisoCodigo').disabled = false;
    document.getElementById('modalPermisoNombre').value = '';
    document.getElementById('modalPermisoDescripcion').value = '';
    document.getElementById('modalPermisoActivo').checked = true;

    abrirModalCustom('modalPermisoCustom');
}
window.abrirModalCrearPermiso = abrirModalCrearPermiso;

function abrirModalEditarPermiso(id) {
    poblarSelectoresModulosRBAC();
    const perm = (cacheRBAC.permisos || []).find(p => Number(p.id || p.Id || p.permisoId || p.PermisoId) === Number(id));
    if (!perm) return;

    document.getElementById('modalPermisoTitle').textContent = 'Editar Acción / Permiso';
    document.getElementById('modalPermisoId').value = perm.id || perm.Id || perm.permisoId || perm.PermisoId;
    document.getElementById('modalPermisoModuloId').value = perm.moduloId || perm.ModuloId;
    document.getElementById('modalPermisoAccion').value = perm.accion || perm.Accion || 'VER';
    document.getElementById('modalPermisoCodigo').value = perm.codigo || perm.Codigo || '';
    document.getElementById('modalPermisoCodigo').disabled = true;
    document.getElementById('modalPermisoNombre').value = perm.nombre || perm.Nombre || '';
    document.getElementById('modalPermisoDescripcion').value = perm.descripcion || perm.Descripcion || '';
    document.getElementById('modalPermisoActivo').checked = perm.activo !== undefined ? perm.activo : (perm.Activo !== undefined ? perm.Activo : true);

    abrirModalCustom('modalPermisoCustom');
}
window.abrirModalEditarPermiso = abrirModalEditarPermiso;

async function guardarPermisoSubmit(e) {
    e.preventDefault();

    const id = document.getElementById('modalPermisoId').value;
    const payload = {
        moduloId: parseInt(document.getElementById('modalPermisoModuloId').value),
        codigo: document.getElementById('modalPermisoCodigo').value.trim().toUpperCase(),
        nombre: document.getElementById('modalPermisoNombre').value.trim(),
        accion: document.getElementById('modalPermisoAccion').value.trim().toUpperCase(),
        descripcion: document.getElementById('modalPermisoDescripcion').value.trim(),
        activo: document.getElementById('modalPermisoActivo').checked
    };

    if (!payload.moduloId || !payload.codigo || !payload.nombre || !payload.accion) {
        if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'Campos Requeridos', text: 'Módulo, Código, Nombre y Acción son obligatorios.' });
        return;
    }

    try {
        const isEdit = !!id;
        const url = isEdit ? `/api/permisos/${id}` : '/api/permisos';
        const method = isEdit ? 'PUT' : 'POST';

        const resp = await fetch(url, {
            method,
            headers: getAuthHeaders(),
            body: JSON.stringify(payload)
        });

        const res = await resp.json();
        if (resp.ok && (res.success || res.Success !== false)) {
            cerrarModalCustom('modalPermisoCustom');
            if (typeof Swal !== 'undefined') {
                Swal.fire({
                    icon: 'success',
                    title: isEdit ? 'Permiso Actualizado' : 'Permiso Creado',
                    text: res.message || res.Message || 'Operación realizada exitosamente.',
                    timer: 1800,
                    showConfirmButton: false
                });
            }
            await cargarModuloPermisos();
        } else {
            const errMsg = res.message || res.Message || (res.errors ? Object.values(res.errors).flat().join(', ') : 'Error al procesar el permiso.');
            throw new Error(errMsg);
        }
    } catch (err) {
        console.error('Error al guardar permiso:', err);
        if (typeof Swal !== 'undefined') {
            Swal.fire({ icon: 'error', title: 'Error', text: err.message });
        }
    }
}
window.guardarPermisoSubmit = guardarPermisoSubmit;

async function eliminarPermisoRBAC(id, nombre) {
    if (typeof Swal === 'undefined') return;

    const result = await Swal.fire({
        icon: 'warning',
        title: '¿Eliminar Acción / Permiso?',
        text: `¿Estás seguro de eliminar el permiso "${nombre}"?`,
        showCancelButton: true,
        confirmButtonText: 'Sí, Eliminar',
        cancelButtonText: 'Cancelar',
        confirmButtonColor: '#e11d48'
    });

    if (result.isConfirmed) {
        try {
            const resp = await fetch(`/api/permisos/${id}`, {
                method: 'DELETE',
                headers: getAuthHeaders()
            });
            const res = await resp.json();
            if (resp.ok && (res.success || res.Success !== false)) {
                Swal.fire({ icon: 'success', title: 'Eliminado', text: res.message || 'Permiso eliminado correctamente.', timer: 1800, showConfirmButton: false });
                await cargarModuloPermisos();
            } else {
                throw new Error(res.message || res.Message || 'No se pudo eliminar el permiso.');
            }
        } catch (err) {
            Swal.fire({ icon: 'error', title: 'No se puede eliminar', text: err.message });
        }
    }
}
window.eliminarPermisoRBAC = eliminarPermisoRBAC;

// =====================================================================
// MÓDULO: TRAZABILIDAD Y CONTROL DE LECHE BÚFALA
// =====================================================================

let stateBufala = {
    modoFiltro: 'semana', // 'semana' | 'rango'
    tipoServicio: 'TODOS', // 'TODOS' | 'RUTA' | 'TRANSPORTE'
    datos: null,
    detalleOriginal: []
};

function cambiarTipoServicioBufala(tipo) {
    stateBufala.tipoServicio = tipo || 'TODOS';
    const btns = document.querySelectorAll('.btn-tipo-bufala');
    btns.forEach(btn => {
        btn.classList.remove('active');
        btn.style.background = 'transparent';
        btn.style.color = '#64748b';
        btn.style.fontWeight = '700';
    });

    const activeBtn = document.getElementById(`btnTipoServicioBufala${tipo === 'TODOS' ? 'Todos' : (tipo === 'RUTA' ? 'Ruta' : 'Transporte')}`);
    if (activeBtn) {
        activeBtn.classList.add('active');
        activeBtn.style.background = '#6366f1';
        activeBtn.style.color = '#ffffff';
        activeBtn.style.fontWeight = '800';
    }

    cargarTrazabilidadBufala();
}
window.cambiarTipoServicioBufala = cambiarTipoServicioBufala;

async function cargarTrazabilidadBufala() {
    try {
        const tbody = document.getElementById('tbodyTrazabilidadBufala');
        if (tbody) {
            tbody.innerHTML = `
                <tr>
                    <td colspan="10" style="text-align: center; padding: 40px; color: #94a3b8;">
                        <i class="fa-solid fa-spinner fa-spin" style="font-size: 24px; margin-bottom: 8px; display: block; color: #0d9488;"></i>
                        Cargando trazabilidad de leche de búfala...
                    </td>
                </tr>`;
        }

        // 1. Inicializar Selectores si están vacíos
        await inicializarSelectoresBufala();

        // 2. Construir Parámetros de Filtro
        let params = new URLSearchParams();

        if (stateBufala.modoFiltro === 'semana') {
            const selSemana = document.getElementById('selectSemanaBufala');
            if (selSemana && selSemana.value) {
                params.append('cicloId', selSemana.value);
            }
        } else {
            const fechaDesde = document.getElementById('filtroFechaDesdeBufala')?.value;
            const fechaHasta = document.getElementById('filtroFechaHastaBufala')?.value;
            if (fechaDesde) params.append('fechaDesde', fechaDesde);
            if (fechaHasta) params.append('fechaHasta', fechaHasta);
        }

        const fincaId = document.getElementById('selectFincaFiltroBufala')?.value;
        if (fincaId) params.append('fincaId', fincaId);

        const companiaId = document.getElementById('selectCompaniaFiltroBufala')?.value;
        if (companiaId) params.append('companiaId', companiaId);

        const usuarioId = document.getElementById('selectChoferFiltroBufala')?.value;
        if (usuarioId) params.append('usuarioId', usuarioId);

        if (stateBufala.tipoServicio && stateBufala.tipoServicio !== 'TODOS') {
            params.append('tipoServicio', stateBufala.tipoServicio);
        }

        // 3. Consultar API Backend
        const resp = await fetch(`${API_BASE}/control-companias/trazabilidad-bufala?${params.toString()}`, {
            headers: { 'Authorization': `Bearer ${state.token}` }
        });

        if (!resp.ok) {
            throw new Error('Error al cargar la trazabilidad de búfala.');
        }

        const data = await resp.json();
        stateBufala.datos = data;
        stateBufala.detalleOriginal = data.detalle || [];

        // 4. Actualizar Tarjetas KPI
        actualizarKpisBufala(data);

        // 5. Renderizar Tablas
        renderTrazabilidadBufala(stateBufala.detalleOriginal);
        renderMatrizBufala(stateBufala.detalleOriginal);
        renderResumenFincasBufala(stateBufala.detalleOriginal);

    } catch (err) {
        console.error('Error en cargarTrazabilidadBufala:', err);
        const tbody = document.getElementById('tbodyTrazabilidadBufala');
        if (tbody) {
            tbody.innerHTML = `
                <tr>
                    <td colspan="10" style="text-align: center; padding: 30px; color: #ef4444; font-weight: 700;">
                        <i class="fa-solid fa-triangle-exclamation" style="font-size: 24px; margin-bottom: 6px; display: block;"></i>
                        ${err.message || 'No se pudo cargar la trazabilidad.'}
                    </td>
                </tr>`;
        }
    }
}
window.cargarTrazabilidadBufala = cargarTrazabilidadBufala;

async function inicializarSelectoresBufala() {
    const selSemana = document.getElementById('selectSemanaBufala');
    const selFinca = document.getElementById('selectFincaFiltroBufala');
    const selComp = document.getElementById('selectCompaniaFiltroBufala');
    const selChofer = document.getElementById('selectChoferFiltroBufala');

    // Cargar en paralelo catálogos si no existen en memoria
    const fetchPromises = [];
    if (selSemana && (selSemana.options.length <= 1 || selSemana.options[0].value === '') && (!state.semanas || state.semanas.length === 0)) {
        fetchPromises.push(fetch(`${API_BASE}/ciclos`, { headers: { 'Authorization': `Bearer ${state.token}` } }).then(r => r.ok ? r.json() : []).then(d => { state.semanas = d; }).catch(() => {}));
    }
    if (selFinca && selFinca.options.length <= 1 && (!state.fincas || state.fincas.length === 0)) {
        fetchPromises.push(fetch(`${API_BASE}/catalogos/fincas`, { headers: { 'Authorization': `Bearer ${state.token}` } }).then(r => r.ok ? r.json() : []).then(d => { state.fincas = d; }).catch(() => {}));
    }
    if (selComp && selComp.options.length <= 1 && (!state.companias || state.companias.length === 0)) {
        fetchPromises.push(fetch(`${API_BASE}/catalogos/companias`, { headers: { 'Authorization': `Bearer ${state.token}` } }).then(r => r.ok ? r.json() : []).then(d => { state.companias = d; }).catch(() => {}));
    }
    if (selChofer && selChofer.options.length <= 1 && (!state.usuarios || state.usuarios.length === 0)) {
        fetchPromises.push(fetch(`${API_BASE}/usuarios`, { headers: { 'Authorization': `Bearer ${state.token}` } }).then(r => r.ok ? r.json() : []).then(d => { state.usuarios = d; }).catch(() => {}));
    }

    if (fetchPromises.length > 0) {
        await Promise.all(fetchPromises);
    }

    // 1. Semanas Operativas
    if (selSemana && (selSemana.options.length <= 1 || selSemana.options[0].value === '') && state.semanas && state.semanas.length > 0) {
        const hoy = new Date().toISOString().split('T')[0];
        const formatF = (d) => {
            if (!d) return '';
            const parts = d.substring(0, 10).split('-');
            return parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : d.substring(0, 10);
        };

        const semanasFiltradas = state.semanas.filter(s => {
            const estado = (s.estado || s.Estado || '').toUpperCase();
            if (estado === 'ABIERTO' || estado === 'CERRADO') return true;
            const fIni = (s.fechaInicio || s.FechaInicio || '').substring(0, 10);
            return fIni && fIni <= hoy;
        });

        semanasFiltradas.sort((a, b) => {
            const estA = (a.estado || a.Estado || '').toUpperCase() === 'ABIERTO' ? 1 : 0;
            const estB = (b.estado || b.Estado || '').toUpperCase() === 'ABIERTO' ? 1 : 0;
            if (estA !== estB) return estB - estA;

            const fA = (a.fechaInicio || a.FechaInicio || '').substring(0, 10);
            const fB = (b.fechaInicio || b.FechaInicio || '').substring(0, 10);
            return fB.localeCompare(fA);
        });

        const listaFinal = semanasFiltradas.length > 0 ? semanasFiltradas : state.semanas;

        selSemana.innerHTML = listaFinal.map(s => {
            const id = s.id || s.Id;
            const semNum = s.numeroSemana || s.NumeroSemana || id;
            const fInicio = s.fechaInicio || s.FechaInicio || '';
            const fFin = s.fechaFin || s.FechaFin || '';
            const formatRango = fInicio ? `${formatF(fInicio)} al ${formatF(fFin)}` : '';
            const estado = (s.estado || s.Estado || '').toUpperCase();
            const esActivo = estado === 'ABIERTO' || s.activo || s.Activo;
            const badgeEstado = esActivo ? '⭐ [ACTIVA]' : (estado ? `[${estado}]` : '');
            return `<option value="${id}" ${esActivo ? 'selected' : ''}>Semana S${semNum} (${formatRango}) ${badgeEstado}</option>`;
        }).join('');
    }

    // 2. Fincas de Búfala
    if (selFinca && selFinca.options.length <= 1 && state.fincas && state.fincas.length > 0) {
        const fincasBufala = state.fincas.filter(f => {
            const nom = (f.nombre || f.Nombre || '').toUpperCase();
            const tieneDos = f.tieneDosTiposLeche || f.TieneDosTiposLeche;
            const pBuf = f.precioBufalaLitroUSD || f.PrecioBufalaLitroUSD;
            return nom.includes('BUFAL') || tieneDos || (pBuf && pBuf > 0);
        });

        const fincasLista = fincasBufala.length > 0 ? fincasBufala : state.fincas;
        selFinca.innerHTML = '<option value="">🏡 TODAS LAS FINCAS DE BÚFALA</option>' +
            fincasLista.map(f => {
                const id = f.id || f.Id;
                const nombre = (f.nombre || f.Nombre || '').trim();
                const prop = (f.propietario || f.Propietario || '').trim();
                const servId = f.tipoServicioId || f.TipoServicioId || 1;
                const servTxt = servId === 2 ? '[TRANSPORTE]' : '[RUTA]';
                return `<option value="${id}">${nombre} (${prop || 'Sin prop.'}) ${servTxt}</option>`;
            }).join('');
    }

    // 3. Compañías
    if (selComp && selComp.options.length <= 1 && state.companias && state.companias.length > 0) {
        selComp.innerHTML = '<option value="">🏢 TODAS LAS COMPAÑÍAS</option>' +
            state.companias.map(c => {
                const id = c.id || c.Id;
                const nombre = (c.nombre || c.Nombre || '').trim();
                const servId = c.tipoServicioId || c.TipoServicioId || 1;
                const servTxt = servId === 2 ? '[TRANSPORTE]' : '[RUTA]';
                return `<option value="${id}">${nombre} ${servTxt}</option>`;
            }).join('');
    }

    // 4. Choferes
    if (selChofer && selChofer.options.length <= 1 && state.usuarios && state.usuarios.length > 0) {
        const choferes = state.usuarios.filter(u => (u.rol || u.Rol || '').toUpperCase() === 'CHOFER' || u.rolId === 2 || (u.rol || u.Rol || '').toUpperCase() === 'ADMIN');
        const listaChof = choferes.length > 0 ? choferes : state.usuarios;
        selChofer.innerHTML = '<option value="">🚚 TODOS LOS CONDUCTORES</option>' +
            listaChof.map(u => {
                const id = u.id || u.Id;
                const nombre = (u.nombreCompleto || u.NombreCompleto || u.username || u.Username || '').trim();
                return `<option value="${id}">${nombre}</option>`;
            }).join('');
    }
}

function actualizarKpisBufala(data) {
    const kpiFincas = document.getElementById('kpiBufalaLitrosFincas');
    if (kpiFincas) kpiFincas.innerHTML = `${(data.totalLitrosFincas || 0).toLocaleString('es-VE')} <small style="font-size: 13px; font-weight: 700; color: #0d9488;">Lts</small>`;

    const kpiRutaFincas = document.getElementById('kpiBufalaFincasRutaLitros');
    if (kpiRutaFincas) kpiRutaFincas.textContent = (data.totalLitrosRuta || 0).toLocaleString('es-VE');

    const kpiTransFincas = document.getElementById('kpiBufalaFincasTransporteLitros');
    if (kpiTransFincas) kpiTransFincas.textContent = (data.totalLitrosTransporte || 0).toLocaleString('es-VE');

    // 2. EN TANQUES RECEPTORÍA
    const kpiTanques = document.getElementById('kpiBufalaLitrosTanques');
    if (kpiTanques) kpiTanques.innerHTML = `${(data.totalLitrosTanques || 0).toLocaleString('es-VE')} <small style="font-size: 13px; font-weight: 700; color: #2563eb;">Lts</small>`;

    // 3. EN COMPAÑÍAS (VENTA / PLANTA)
    const kpiCompanias = document.getElementById('kpiBufalaLitrosCompanias');
    if (kpiCompanias) kpiCompanias.innerHTML = `${(data.totalLitrosCompaniasDirectas || 0).toLocaleString('es-VE')} <small style="font-size: 13px; font-weight: 700; color: #7e22ce;">Lts</small>`;

    const kpiCompRuta = document.getElementById('kpiBufalaCompaniasRutaLitros');
    if (kpiCompRuta) kpiCompRuta.textContent = (data.totalCompaniasDirectasRuta || 0).toLocaleString('es-VE');

    const kpiCompTrans = document.getElementById('kpiBufalaCompaniasTransporteLitros');
    if (kpiCompTrans) kpiCompTrans.textContent = (data.totalCompaniasDirectasTransporte || 0).toLocaleString('es-VE');

    // 4. MERMA Y BALANCE GLOBAL
    const kpiMerma = document.getElementById('kpiBufalaMermaLitros');
    const dif = data.totalDiferenciaLitros || 0;
    if (kpiMerma) {
        const sign = dif > 0 ? '-' : (dif < 0 ? '+' : '');
        kpiMerma.innerHTML = `${sign}${Math.abs(dif).toLocaleString('es-VE')} <small style="font-size: 13px; font-weight: 700; color: #c2410c;">Lts</small>`;
    }

    const kpiMermaPct = document.getElementById('kpiBufalaMermaPct');
    if (kpiMermaPct) {
        kpiMermaPct.textContent = `${(data.porcentajeMermaGlobal || 0).toFixed(2)}% Merma`;
        kpiMermaPct.style.color = (data.porcentajeMermaGlobal || 0) > 1.0 ? '#e11d48' : '#059669';
    }

    // 5. VIAJES
    const kpiViajes = document.getElementById('kpiBufalaViajesCount');
    if (kpiViajes) kpiViajes.innerHTML = `${data.cantidadViajes || 0} <small style="font-size: 13px; font-weight: 700; color: #0369a1;">Viajes</small>`;

    const kpiPromedio = document.getElementById('kpiBufalaPromedioPorViaje');
    if (kpiPromedio) {
        const promedio = data.cantidadViajes > 0 ? Math.round(data.totalLitrosFincas / data.cantidadViajes) : 0;
        kpiPromedio.textContent = `${promedio.toLocaleString('es-VE')} Lts promedio / viaje`;
    }
}

function renderTrazabilidadBufala(lista) {
    const tbody = document.getElementById('tbodyTrazabilidadBufala');
    const lblContador = document.getElementById('lblContadorTrazabilidadBufala');
    if (lblContador) lblContador.textContent = `${lista.length} Registros`;

    if (!tbody) return;

    if (!lista || lista.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="10" style="text-align: center; padding: 40px; color: #94a3b8; font-weight: 600;">
                    <i class="fa-solid fa-cow" style="font-size: 28px; margin-bottom: 8px; display: block; opacity: 0.5;"></i>
                    No se encontraron registros de leche de búfala con los filtros aplicados.
                </td>
            </tr>`;
        return;
    }

    tbody.innerHTML = lista.map((item, idx) => {
        const fechaRaw = item.fecha ? item.fecha.substring(0, 10) : '';
        let fechaFormateada = fechaRaw;
        let diaNom = '';
        if (fechaRaw) {
            const parts = fechaRaw.split('-');
            if (parts.length === 3) {
                fechaFormateada = `${parts[2]}/${parts[1]}/${parts[0]}`;
                const dt = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10), 12, 0, 0);
                const diasSemana = ['DOMINGO', 'LUNES', 'MARTES', 'MIÉRCOLES', 'JUEVES', 'VIERNES', 'SÁBADO'];
                diaNom = diasSemana[dt.getDay()];
            }
        }

        const semTag = item.cicloId ? `<span class="badge" style="background:#e0f2fe; color:#0369a1; font-size:10px; font-weight:800; padding:1px 5px; border-radius:4px; margin-right:4px;">S${item.cicloId}</span>` : '';

        const esTransporte = (item.tipoServicio || '').toUpperCase() === 'TRANSPORTE';
        const badgeServicio = esTransporte 
            ? '<span class="badge" style="background:#fef3c7; color:#92400e; border:1px solid #fde68a; font-weight:800; font-size:10.5px; padding:2px 7px;">🚛 TRANSPORTE</span>'
            : '<span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; font-weight:800; font-size:10.5px; padding:2px 7px;">🏠 RUTA</span>';

        const difLitros = item.diferenciaLitros || 0;
        const pctMerma = item.porcentajeMerma || 0;
        let mermaBadge = '<span class="badge" style="background:#ecfdf5; color:#047857; font-weight:700; font-size:11px;">0 L (Exacto)</span>';
        if (difLitros > 0) {
            mermaBadge = `<span class="badge" style="background:#fee2e2; color:#b91c1c; font-weight:800; font-size:11px;">-${difLitros} L (${pctMerma.toFixed(2)}%)</span>`;
        } else if (difLitros < 0) {
            mermaBadge = `<span class="badge" style="background:#eff6ff; color:#1d4ed8; font-weight:800; font-size:11px;">+${Math.abs(difLitros)} L (Sobrante)</span>`;
        }

        const estadoColor = item.estadoViaje === 'FINALIZADO' || item.estadoViaje === 'CERRADO' ? '#059669' : '#d97706';
        const estadoBg = item.estadoViaje === 'FINALIZADO' || item.estadoViaje === 'CERRADO' ? '#ecfdf5' : '#fffbeb';

        const totalDespacho = item.litrosRecibidosCompania || item.litrosDespachadosCompania || 0;

        return `
            <tr style="border-bottom: 1px solid #f1f5f9; transition: all 0.2s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='transparent'">
                <td style="padding: 12px 14px; text-align: center; white-space: nowrap;">
                    ${semTag}
                    <strong style="color: #0f172a; font-size: 13px;">${fechaFormateada}</strong>
                    <br><small style="color: #0d9488; font-weight: 800; font-size: 10.5px; text-transform: uppercase;">${diaNom}</small>
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    ${badgeServicio}
                </td>
                <td style="padding: 12px 14px;">
                    <div style="display: flex; align-items: center; gap: 6px;">
                        <span class="badge" style="background: #f0fdfa; color: #0d9488; border: 1px solid #99f6e4; font-size: 10px; font-weight: 800; padding: 2px 6px; border-radius: 4px;">🐃 BÚFALA</span>
                        <strong style="color: #0f172a; font-size: 13.5px;">${item.fincaNombre}</strong>
                    </div>
                    <small style="color: #64748b; display: block; margin-top: 2px;">
                        <i class="fa-solid fa-user-tag" style="color: #94a3b8; font-size: 10px;"></i> ${item.propietario}
                    </small>
                </td>
                <td style="padding: 12px 14px; text-align: right;">
                    <strong style="color: #059669; font-size: 14.5px; font-family: monospace;">
                        ${(item.litrosFinca || 0).toLocaleString('es-VE')}
                    </strong>
                    <span style="font-size: 11px; color: #059669; font-weight: 700;">Lts</span>
                </td>
                <td style="padding: 12px 14px;">
                    <strong style="color: #1e293b; font-size: 13px;">${item.choferNombre}</strong>
                    ${item.controlRutaId ? `<br><span class="badge badge-info" style="font-size: 10.5px; font-weight: 800; cursor: pointer; display: inline-flex; align-items: center; gap: 4px; margin-top: 3px;" onclick="if(typeof abrirModalTrazabilidadViaje==='function') abrirModalTrazabilidadViaje(${item.controlRutaId})" title="Ver trazabilidad del viaje"><i class="fa-solid fa-route"></i> Ticket #${item.controlRutaId}</span>` : ''}
                </td>
                <td style="padding: 12px 14px;">
                    ${(() => {
                        const esTanque = item.esTanqueReceptoria || (item.companiaNombre || '').toUpperCase().includes('RECEPTORIA');
                        if (esTanque) {
                            return `
                                <div style="display: flex; flex-direction: column; gap: 3px;">
                                    <div style="display: inline-flex; align-items: center; gap: 6px;">
                                        <span class="badge" style="background: #e0f2fe; color: #0369a1; border: 1.5px solid #7dd3fc; font-weight: 800; font-size: 11px; padding: 3px 8px; border-radius: 6px; box-shadow: 0 1px 3px rgba(3,105,161,0.08);">
                                            <i class="fa-solid fa-boxes-stacked" style="color: #0284c7;"></i> TANQUES (Receptoría Acopio)
                                        </span>
                                    </div>
                                    ${item.controlCompaniaId ? `<small style="color: #64748b; font-weight: 600; font-size: 11px;">Entrada a Tanque #${item.controlCompaniaId} ${totalDespacho > 0 ? `(${totalDespacho.toLocaleString('es-VE')} L)` : ''}</small>` : ''}
                                    ${item.destinosFinales ? `
                                        <div style="display: inline-flex; align-items: center; gap: 5px; background: #faf5ff; padding: 2px 8px; border-radius: 6px; border: 1px solid #e9d5ff; font-size: 11px; color: #6b21a8; font-weight: 700; margin-top: 2px;">
                                            <i class="fa-solid fa-arrow-right" style="color: #9333ea; font-size: 10px;"></i>
                                            <span>Salida / Destino: <strong>${item.destinosFinales}</strong></span>
                                        </div>
                                    ` : `<small style="color: #94a3b8; font-style: italic; font-size: 10.5px;">En Tanque de Almacenamiento</small>`}
                                </div>`;
                        } else {
                            return `
                                <div style="display: flex; flex-direction: column; gap: 3px;">
                                    <div style="display: inline-flex; align-items: center; gap: 6px;">
                                        <span class="badge" style="background: #faf5ff; color: #7e22ce; border: 1.5px solid #d8b4fe; font-weight: 800; font-size: 11px; padding: 3px 8px; border-radius: 6px;">
                                            <i class="fa-solid fa-building" style="color: #9333ea;"></i> ${item.companiaNombre || 'Sin Asignar'}
                                        </span>
                                    </div>
                                    ${item.controlCompaniaId ? `<small style="color: #64748b; font-weight: 600; font-size: 11px;">Despacho Directo #${item.controlCompaniaId} ${totalDespacho > 0 ? `(${totalDespacho.toLocaleString('es-VE')} L)` : ''}</small>` : ''}
                                </div>`;
                        }
                    })()}
                </td>
                <td style="padding: 12px 14px; text-align: right;">
                    ${item.litrosRecibidosCompania != null ? `
                        <strong style="color: #7c3aed; font-size: 14px; font-family: monospace;">
                            ${(item.litrosFinca || item.litrosRecibidosCompania).toLocaleString('es-VE')}
                        </strong>
                        <span style="font-size: 11px; color: #7c3aed; font-weight: 700;">Lts</span>
                        ${totalDespacho > (item.litrosFinca || 0) ? `<small style="color: #64748b; font-size: 10px; display: block;">de ${totalDespacho.toLocaleString('es-VE')} L viaje</small>` : ''}
                    ` : `<span style="color: #94a3b8; font-size: 12px; font-style: italic;">En Tránsito</span>`}
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    ${mermaBadge}
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    <span class="badge" style="background: ${estadoBg}; color: ${estadoColor}; font-weight: 800; font-size: 10.5px; border-radius: 6px; padding: 3px 8px;">
                        ${item.estadoViaje || 'FINALIZADO'}
                    </span>
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    ${item.controlRutaId ? `
                        <button type="button" class="btn-icon" onclick="if(typeof abrirModalTrazabilidadViaje==='function') abrirModalTrazabilidadViaje(${item.controlRutaId})" title="Ver trazabilidad completa del ticket #${item.controlRutaId}" style="width: 32px; height: 32px; border-radius: 8px; border: 1px solid #bae6fd; background: #f0f9ff; color: #0284c7; cursor: pointer; display: inline-flex; align-items: center; justify-content: center;">
                            <i class="fa-solid fa-eye"></i>
                        </button>
                    ` : '-'}
                </td>
            </tr>`;
    }).join('');
}

function renderMatrizBufala(lista) {
    const tbody = document.getElementById('tbodyMatrizBufala');
    const tfoot = document.getElementById('tfootMatrizBufala');
    if (!tbody) return;

    if (!lista || lista.length === 0) {
        tbody.innerHTML = `<tr><td colspan="11" style="text-align:center; padding:30px; color:#94a3b8;">No hay entregas para mostrar en la matriz.</td></tr>`;
        if (tfoot) tfoot.innerHTML = '';
        return;
    }

    // Agrupar por Compañía de Destino
    let matriz = {};
    let totalGeneral = 0;
    let totalesDias = [0, 0, 0, 0, 0, 0, 0]; // Lun, Mar, Mie, Jue, Vie, Sab, Dom

    lista.forEach(item => {
        const comp = item.companiaNombre || 'Sin Destino / En Ruta';
        const tipoServ = (item.tipoServicio || 'RUTA').toUpperCase();
        if (!matriz[comp]) {
            matriz[comp] = {
                nombre: comp,
                esTanque: item.esTanqueReceptoria || comp.toUpperCase().includes('RECEPTORIA'),
                tipoServicio: tipoServ,
                dias: [0, 0, 0, 0, 0, 0, 0],
                total: 0
            };
        }

        const lts = item.litrosFinca || item.litrosRecibidosCompania || 0;
        if (item.fecha) {
            const fechaRaw = item.fecha.substring(0, 10);
            const parts = fechaRaw.split('-');
            if (parts.length === 3) {
                const dt = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10), 12, 0, 0);
                const dayOfWeek = dt.getDay(); // 0=Dom, 1=Lun, ..., 6=Sab
                const colIdx = (dayOfWeek + 6) % 7; // 0=Lun, 1=Mar, ..., 6=Dom
                matriz[comp].dias[colIdx] += lts;
                matriz[comp].total += lts;
                totalesDias[colIdx] += lts;
                totalGeneral += lts;
            }
        }
    });

    const companias = Object.values(matriz).sort((a, b) => b.total - a.total);

    tbody.innerHTML = companias.map(c => {
        const pct = totalGeneral > 0 ? ((c.total * 100.0) / totalGeneral).toFixed(1) : '0.0';
        const esTrans = c.tipoServicio === 'TRANSPORTE';
        const badgeServ = esTrans 
            ? '<span class="badge" style="background:#fef3c7; color:#92400e; border:1px solid #fde68a; font-size:10.5px; font-weight:800; padding:1px 6px;">TRANSPORTE</span>'
            : '<span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; font-size:10.5px; font-weight:800; padding:1px 6px;">RUTA</span>';

        const nombreHtml = c.esTanque 
            ? `<span style="color: #0369a1; font-weight: 800;"><i class="fa-solid fa-boxes-stacked" style="color: #0284c7; margin-right: 6px;"></i> TANQUES (Receptoría Acopio)</span>`
            : `<span style="color: #1e1b4b; font-weight: 800;"><i class="fa-solid fa-building" style="color: #7c3aed; margin-right: 6px;"></i> ${c.nombre}</span>`;

        return `
            <tr style="border-bottom: 1px solid #f1f5f9;">
                <td style="padding: 12px 14px; display: flex; align-items: center; gap: 8px;">
                    ${nombreHtml}
                </td>
                <td style="padding: 12px 10px; text-align: center;">
                    ${badgeServ}
                </td>
                ${c.dias.map(d => `<td style="padding: 12px 10px; text-align: right; font-family: monospace; font-weight: 700; color: ${d > 0 ? '#0f172a' : '#cbd5e1'};">${d > 0 ? d.toLocaleString('es-VE') : '-'}</td>`).join('')}
                <td style="padding: 12px 14px; text-align: right; font-family: monospace; font-weight: 900; color: #7c3aed; background: #faf5ff;">
                    ${c.total.toLocaleString('es-VE')} Lts
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    <span class="badge" style="background: #f1f5f9; color: #475569; font-weight: 800; font-size: 11px;">${pct}%</span>
                </td>
            </tr>`;
    }).join('');

    if (tfoot) {
        tfoot.innerHTML = `
            <tr>
                <td colspan="2" style="padding: 12px 14px; font-weight: 900; color: #0f172a; text-transform: uppercase;">
                    <i class="fa-solid fa-sigma"></i> TOTALES CONSOLIDADOS
                </td>
                ${totalesDias.map(td => `<td style="padding: 12px 10px; text-align: right; font-family: monospace; font-weight: 900; color: #0f172a;">${td > 0 ? td.toLocaleString('es-VE') : '-'}</td>`).join('')}
                <td style="padding: 12px 14px; text-align: right; font-family: monospace; font-weight: 900; color: #059669; font-size: 14px; background: #ecfdf5;">
                    ${totalGeneral.toLocaleString('es-VE')} Lts
                </td>
                <td style="padding: 12px 14px; text-align: center; font-weight: 900; color: #059669;">
                    100%
                </td>
            </tr>`;
    }
}

function renderResumenFincasBufala(lista) {
    const tbody = document.getElementById('tbodyResumenFincasBufala');
    const tfoot = document.getElementById('tfootResumenFincasBufala');
    const lblTotal = document.getElementById('lblTotalFincasBufalaResumen');
    if (!tbody) return;

    if (!lista || lista.length === 0) {
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:30px; color:#94a3b8;">No hay datos de fincas.</td></tr>`;
        if (tfoot) tfoot.innerHTML = '';
        return;
    }

    let fincasMap = {};
    let totalLitros = 0;

    lista.forEach(item => {
        const id = item.fincaId || item.fincaNombre;
        if (!fincasMap[id]) {
            fincasMap[id] = {
                id: item.fincaId,
                nombre: item.fincaNombre,
                propietario: item.propietario,
                tipoServicio: (item.tipoServicio || 'RUTA').toUpperCase(),
                litros: 0,
                dias: new Set(),
                companias: new Set()
            };
        }
        fincasMap[id].litros += (item.litrosFinca || 0);
        totalLitros += (item.litrosFinca || 0);
        if (item.fecha) fincasMap[id].dias.add(item.fecha.substring(0, 10));
        if (item.companiaNombre) {
            const compLabel = (item.esTanqueReceptoria || item.companiaNombre.toUpperCase().includes('RECEPTORIA'))
                ? 'TANQUES (Receptoría)'
                : item.companiaNombre;
            fincasMap[id].companias.add(compLabel);
        }
    });

    const fincasArray = Object.values(fincasMap).sort((a, b) => b.litros - a.litros);
    if (lblTotal) lblTotal.textContent = `${fincasArray.length} Fincas productoras`;

    tbody.innerHTML = fincasArray.map(f => {
        const pct = totalLitros > 0 ? ((f.litros * 100.0) / totalLitros).toFixed(1) : '0.0';
        const compsBadges = Array.from(f.companias).map(c => {
            const esTnk = c.includes('TANQUES');
            return esTnk 
                ? `<span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #7dd3fc; font-size:10.5px; font-weight:800; margin-right:3px;"><i class="fa-solid fa-boxes-stacked"></i> ${c}</span>`
                : `<span class="badge" style="background:#faf5ff; color:#7e22ce; border:1px solid #d8b4fe; font-size:10.5px; font-weight:700; margin-right:3px;"><i class="fa-solid fa-building"></i> ${c}</span>`;
        }).join('') || '<span style="color:#94a3b8;">Sin asignar</span>';

        const esTrans = f.tipoServicio === 'TRANSPORTE';
        const badgeServ = esTrans 
            ? '<span class="badge" style="background:#fef3c7; color:#92400e; border:1px solid #fde68a; font-size:10.5px; font-weight:800; padding:1px 6px;">TRANSPORTE</span>'
            : '<span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; font-size:10.5px; font-weight:800; padding:1px 6px;">RUTA</span>';

        return `
            <tr style="border-bottom: 1px solid #f1f5f9;">
                <td style="padding: 12px 14px; font-weight: 800; color: #064e3b;">
                    <i class="fa-solid fa-seedling" style="color: #10b981; margin-right: 6px;"></i> ${f.nombre}
                </td>
                <td style="padding: 12px 14px; color: #475569; font-weight: 600;">
                    ${f.propietario}
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    ${badgeServ}
                </td>
                <td style="padding: 12px 14px; text-align: right; font-family: monospace; font-weight: 900; color: #059669; font-size: 14px;">
                    ${f.litros.toLocaleString('es-VE')} Lts
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    <span class="badge badge-info" style="font-weight: 800; font-size: 11px;">${f.dias.size} días</span>
                </td>
                <td style="padding: 12px 14px;">
                    ${compsBadges}
                </td>
                <td style="padding: 12px 14px; text-align: center;">
                    <span class="badge" style="background: #ecfdf5; color: #047857; font-weight: 900; font-size: 11.5px;">${pct}%</span>
                </td>
            </tr>`;
    }).join('');

    if (tfoot) {
        tfoot.innerHTML = `
            <tr>
                <td colspan="3" style="padding: 12px 14px; font-weight: 900; color: #064e3b; text-transform: uppercase;">
                    TOTAL APORTE FINCAS BÚFALA
                </td>
                <td style="padding: 12px 14px; text-align: right; font-family: monospace; font-weight: 900; color: #059669; font-size: 14.5px;">
                    ${totalLitros.toLocaleString('es-VE')} Lts
                </td>
                <td colspan="2"></td>
                <td style="padding: 12px 14px; text-align: center; font-weight: 900; color: #059669;">
                    100%
                </td>
            </tr>`;
    }
}

function conmutarSubPestanaBufala(subtab) {
    const tabs = ['trazabilidad', 'matriz', 'fincas'];
    tabs.forEach(t => {
        const btn = document.getElementById('btnSubtabBufala' + t.charAt(0).toUpperCase() + t.slice(1));
        const panel = document.getElementById('panelBufala' + t.charAt(0).toUpperCase() + t.slice(1));
        if (t === subtab) {
            if (btn) {
                btn.classList.add('active');
                btn.style.background = '#0d9488';
                btn.style.color = '#ffffff';
                btn.style.border = 'none';
            }
            if (panel) panel.style.display = 'block';
        } else {
            if (btn) {
                btn.classList.remove('active');
                btn.style.background = '#ffffff';
                btn.style.color = '#475569';
                btn.style.border = '1.5px solid #cbd5e1';
            }
            if (panel) panel.style.display = 'none';
        }
    });
}
window.conmutarSubPestanaBufala = conmutarSubPestanaBufala;

function cambiarModoFiltroBufala(modo) {
    stateBufala.modoFiltro = modo;
    const btnSem = document.getElementById('btnModoBufalaSemana');
    const btnRango = document.getElementById('btnModoBufalaRango');
    const wrapSem = document.getElementById('wrapperControlesSemanaBufala');
    const wrapRango = document.getElementById('wrapperControlesRangoBufala');

    if (modo === 'semana') {
        if (btnSem) { btnSem.classList.add('active'); btnSem.style.background = '#0d9488'; btnSem.style.color = '#fff'; }
        if (btnRango) { btnRango.classList.remove('active'); btnRango.style.background = 'transparent'; btnRango.style.color = '#64748b'; }
        if (wrapSem) wrapSem.style.display = 'flex';
        if (wrapRango) wrapRango.style.display = 'none';
    } else {
        if (btnRango) { btnRango.classList.add('active'); btnRango.style.background = '#0d9488'; btnRango.style.color = '#fff'; }
        if (btnSem) { btnSem.classList.remove('active'); btnSem.style.background = 'transparent'; btnSem.style.color = '#64748b'; }
        if (wrapSem) wrapSem.style.display = 'none';
        if (wrapRango) wrapRango.style.display = 'flex';
    }
    cargarTrazabilidadBufala();
}
window.cambiarModoFiltroBufala = cambiarModoFiltroBufala;

function navegarSemanaBufala(delta) {
    const sel = document.getElementById('selectSemanaBufala');
    if (!sel || sel.options.length <= 1) return;

    let newIndex = sel.selectedIndex + delta;
    if (newIndex >= 0 && newIndex < sel.options.length) {
        sel.selectedIndex = newIndex;
        cargarTrazabilidadBufala();
    }
}
window.navegarSemanaBufala = navegarSemanaBufala;

function filtrarTablaTrazabilidadBufalaLive() {
    const query = (document.getElementById('buscadorTrazabilidadBufala')?.value || '').toLowerCase().trim();
    if (!stateBufala.detalleOriginal) return;

    if (!query) {
        renderTrazabilidadBufala(stateBufala.detalleOriginal);
        return;
    }

    const filtrados = stateBufala.detalleOriginal.filter(item => {
        const serv = (item.tipoServicio || '').toLowerCase();
        const finca = (item.fincaNombre || '').toLowerCase();
        const prop = (item.propietario || '').toLowerCase();
        const chofer = (item.choferNombre || '').toLowerCase();
        const comp = (item.companiaNombre || '').toLowerCase();
        const ticket = String(item.controlRutaId || '');
        const fecha = (item.fecha || '').toLowerCase();
        return serv.includes(query) || finca.includes(query) || prop.includes(query) || chofer.includes(query) || comp.includes(query) || ticket.includes(query) || fecha.includes(query);
    });

    renderTrazabilidadBufala(filtrados);
}
window.filtrarTablaTrazabilidadBufalaLive = filtrarTablaTrazabilidadBufalaLive;

function limpiarFiltrosBufala() {
    stateBufala.tipoServicio = 'TODOS';
    const btns = document.querySelectorAll('.btn-tipo-bufala');
    btns.forEach(btn => {
        btn.classList.remove('active');
        btn.style.background = 'transparent';
        btn.style.color = '#64748b';
        btn.style.fontWeight = '700';
    });
    const btnTodos = document.getElementById('btnTipoServicioBufalaTodos');
    if (btnTodos) {
        btnTodos.classList.add('active');
        btnTodos.style.background = '#6366f1';
        btnTodos.style.color = '#fff';
        btnTodos.style.fontWeight = '800';
    }

    const selFinca = document.getElementById('selectFincaFiltroBufala');
    if (selFinca) selFinca.value = '';

    const selComp = document.getElementById('selectCompaniaFiltroBufala');
    if (selComp) selComp.value = '';

    const selChofer = document.getElementById('selectChoferFiltroBufala');
    if (selChofer) selChofer.value = '';

    const inputBuscador = document.getElementById('buscadorTrazabilidadBufala');
    if (inputBuscador) inputBuscador.value = '';

    cargarTrazabilidadBufala();
}
window.limpiarFiltrosBufala = limpiarFiltrosBufala;

function exportarReporteBufalaExcel() {
    if (!stateBufala.detalleOriginal || stateBufala.detalleOriginal.length === 0) {
        Swal.fire({ icon: 'info', title: 'Sin Datos', text: 'No hay registros de búfala para exportar.' });
        return;
    }

    const encabezados = [
        'ID',
        'Fecha',
        'Semana',
        'Tipo Servicio',
        'Finca',
        'Propietario',
        'Tipo Leche',
        'Litros Finca',
        'Chofer',
        'Ticket Ruta',
        'Compañia Destino',
        'Despacho ID',
        'Litros Recibidos Planta',
        'Diferencia Litros',
        'Porcentaje Merma',
        'Estado Viaje',
        'Observacion'
    ];

    const filas = stateBufala.detalleOriginal.map(item => [
        item.id || '',
        item.fecha ? item.fecha.substring(0, 10) : '',
        item.cicloId ? `S${item.cicloId}` : '',
        `"${item.tipoServicio || 'RUTA'}"`,
        `"${(item.fincaNombre || '').replace(/"/g, '""')}"`,
        `"${(item.propietario || '').replace(/"/g, '""')}"`,
        item.tipoLeche || 'BUFALA',
        item.litrosFinca || 0,
        `"${(item.choferNombre || '').replace(/"/g, '""')}"`,
        item.controlRutaId || '',
        `"${(item.companiaNombre || '').replace(/"/g, '""')}"`,
        item.controlCompaniaId || '',
        item.litrosRecibidosCompania || '',
        item.diferenciaLitros || 0,
        item.porcentajeMerma || 0,
        item.estadoViaje || '',
        `"${(item.observacion || '').replace(/"/g, '""')}"`
    ]);

    const csvContent = '\uFEFF' + [encabezados.join(';'), ...filas.map(f => f.join(';'))].join('\r\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Trazabilidad_Bufala_${new Date().toISOString().substring(0, 10)}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}
window.exportarReporteBufalaExcel = exportarReporteBufalaExcel;

// ==========================================================================
// MÓDULO CRUD: CONFIGURACIÓN DE EMPRESA & MEMBRETE OFICIAL
// ==========================================================================
var empresaConfigData = window.empresaConfigData || null;

async function cargarEmpresaConfig(forceReload = false) {
    try {
        if (!forceReload && empresaConfigData) {
            popularFormularioEmpresa(empresaConfigData);
            return empresaConfigData;
        }

        const res = await fetch(`${API_BASE}/catalogos/empresa`, {
            headers: state.token ? { 'Authorization': `Bearer ${state.token}` } : {}
        });

        if (res.ok) {
            const data = await res.json();
            empresaConfigData = data;
            window.empresaConfigData = data;
            popularFormularioEmpresa(data);
            return data;
        } else {
            console.warn('No se pudo cargar la configuración de empresa.');
        }
    } catch (err) {
        console.error('Error al cargar datos de empresa:', err);
    }
}
window.cargarEmpresaConfig = cargarEmpresaConfig;

function popularFormularioEmpresa(data) {
    if (!data) return;
    const inputId = document.getElementById('empresaConfigId');
    const inputNombre = document.getElementById('empresaNombre');
    const inputRif = document.getElementById('empresaRif');
    const inputTelefono = document.getElementById('empresaTelefono');
    const inputEmail = document.getElementById('empresaEmail');
    const inputDireccion = document.getElementById('empresaDireccion');
    const inputLogoUrl = document.getElementById('empresaLogoUrl');

    if (inputId) inputId.value = data.id || 1;
    if (inputNombre) inputNombre.value = data.nombre || 'TRANSPORTE VERGEL & CARRILLO';
    if (inputRif) inputRif.value = data.rif || 'J-50000000-0';
    if (inputTelefono) inputTelefono.value = data.telefono || '+58 414-0000000';
    if (inputEmail) inputEmail.value = data.email || 'contacto@transporte-vergel-carrillo.com';
    if (inputDireccion) inputDireccion.value = data.direccion || 'Carretera Nacional, Sector El Cruce, Estado Zulia, Venezuela';
    if (inputLogoUrl) inputLogoUrl.value = data.logoUrl || '';

    actualizarPreviewMembreteLive();
}
window.popularFormularioEmpresa = popularFormularioEmpresa;

function actualizarPreviewMembreteLive() {
    const nombre = document.getElementById('empresaNombre')?.value || 'TRANSPORTE VERGEL & CARRILLO';
    const rif = document.getElementById('empresaRif')?.value || 'J-50000000-0';
    const telefono = document.getElementById('empresaTelefono')?.value || '';
    const email = document.getElementById('empresaEmail')?.value || '';
    const direccion = document.getElementById('empresaDireccion')?.value || 'Carretera Nacional, Sector El Cruce, Estado Zulia, Venezuela';
    const logoUrl = document.getElementById('empresaLogoUrl')?.value || '';

    // Actualizar preview en la vista
    const liveNombre = document.getElementById('liveMembreteNombre');
    const liveRif = document.getElementById('liveMembreteRif');
    const liveDireccion = document.getElementById('liveMembreteDireccion');
    const liveLogoBox = document.getElementById('liveMembreteLogoBox');
    const thumbnailBox = document.getElementById('previewLogoThumbnail');

    if (liveNombre) liveNombre.innerText = nombre.toUpperCase();
    if (liveRif) liveRif.innerText = rif.toUpperCase();
    if (liveDireccion) liveDireccion.innerText = direccion;

    if (logoUrl && logoUrl.trim().length > 10) {
        if (liveLogoBox) liveLogoBox.innerHTML = `<img src="${logoUrl}" alt="Logo" style="width: 100%; height: 100%; object-fit: contain;">`;
        if (thumbnailBox) thumbnailBox.innerHTML = `<img src="${logoUrl}" alt="Logo" style="width: 100%; height: 100%; object-fit: contain;">`;
    } else {
        if (liveLogoBox) liveLogoBox.innerHTML = `<i class="fa-solid fa-truck-droplet" style="color: #38bdf8;"></i>`;
        if (thumbnailBox) thumbnailBox.innerHTML = `<i class="fa-solid fa-truck-droplet"></i>`;
    }
}
window.actualizarPreviewMembreteLive = actualizarPreviewMembreteLive;

function onSeleccionarArchivoLogo(event) {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) {
        Swal.fire('Imagen muy pesada', 'Por favor selecciona una imagen menor a 2MB.', 'warning');
        return;
    }

    const reader = new FileReader();
    reader.onload = function (e) {
        const base64Data = e.target.result;
        const inputLogoUrl = document.getElementById('empresaLogoUrl');
        if (inputLogoUrl) inputLogoUrl.value = base64Data;
        actualizarPreviewMembreteLive();
    };
    reader.readAsDataURL(file);
}
window.onSeleccionarArchivoLogo = onSeleccionarArchivoLogo;

async function guardarEmpresaConfigForm(event) {
    if (event && typeof event.preventDefault === 'function') event.preventDefault();

    const id = Number(document.getElementById('empresaConfigId')?.value || 1);
    const nombre = (document.getElementById('empresaNombre')?.value || '').trim();
    const rif = (document.getElementById('empresaRif')?.value || '').trim();
    const telefono = (document.getElementById('empresaTelefono')?.value || '').trim();
    const email = (document.getElementById('empresaEmail')?.value || '').trim();
    const direccion = (document.getElementById('empresaDireccion')?.value || '').trim();
    const logoUrl = (document.getElementById('empresaLogoUrl')?.value || '').trim();

    if (!nombre) {
        Swal.fire('Campo Requerido', 'El nombre o razón social de la empresa es obligatorio.', 'warning');
        return;
    }
    if (!rif) {
        Swal.fire('Campo Requerido', 'El RIF o identificación fiscal de la empresa es obligatorio.', 'warning');
        return;
    }

    const payload = {
        id: id,
        nombre: nombre,
        rif: rif,
        telefono: telefono,
        email: email,
        direccion: direccion,
        logoUrl: logoUrl
    };

    try {
        Swal.fire({
            title: 'Guardando Configuración...',
            text: 'Actualizando datos oficiales de la empresa en la base de datos...',
            allowOutsideClick: false,
            didOpen: () => Swal.showLoading(),
            background: '#1e293b',
            color: '#fff'
        });

        const res = await fetch(`${API_BASE}/catalogos/empresa`, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json',
                ...(state.token ? { 'Authorization': `Bearer ${state.token}` } : {})
            },
            body: JSON.stringify(payload)
        });

        if (res.ok) {
            empresaConfigData = payload;
            window.empresaConfigData = payload;
            Swal.fire({
                icon: 'success',
                title: '¡Configuración Guardada!',
                html: `Los datos de <strong>${nombre}</strong> se han actualizado correctamente en el sistema.`,
                confirmButtonColor: '#10b981',
                background: '#1e293b',
                color: '#fff'
            });
            actualizarPreviewMembreteLive();
        } else {
            const errData = await res.json().catch(() => ({}));
            Swal.fire({
                icon: 'error',
                title: 'Error al Guardar',
                text: errData.mensaje || 'No se pudo guardar la configuración de empresa.',
                background: '#1e293b',
                color: '#fff'
            });
        }
    } catch (err) {
        console.error('Error al guardar empresa:', err);
        Swal.fire({
            icon: 'error',
            title: 'Error de Red',
            text: 'Ocurrió un fallo de conexión al intentar guardar.',
            background: '#1e293b',
            color: '#fff'
        });
    }
}
window.guardarEmpresaConfigForm = guardarEmpresaConfigForm;

// ============================================================================
// MÓDULO DE PARAMETRIZACIÓN Y CONFIGURACIÓN GLOBAL DEL SISTEMA (V2)
// Tablas: TB_PARAMETROS_SISTEMA, TB_TIPOS_LECHE, TB_MODULOS, TB_REPORTES_CONFIG, TB_DASHBOARD_WIDGETS
// ============================================================================

window.parametrosSistemaDataCache = [];
window.tiposLecheDataCache = [];
window.modulosMenuDataCache = [];
window.reportesConfigDataCache = [];
window.widgetsDashboardDataCache = [];

// ==========================================================================
// MÓDULO DE CONFIGURACIÓN Y PARAMETRIZACIÓN DEL SISTEMA
// ==========================================================================

/**
 * Gestiona el cambio de pestañas secundarias dentro del módulo de Configuración.
 * 
 * Qué hace esta función:
 * 1. Oculta todos los paneles secundarios (`.subtab-panel-config` y `subtab-config-*`).
 * 2. Remueve la clase activa de todos los botones de sub-pestaña.
 * 3. Muestra el panel seleccionado (`subtab-config-${subTabKey}`).
 * 4. Ajusta la visibilidad de los botones de acción rápida en la barra superior.
 * 
 * @param {string} subTabKey - Clave de la subpestaña ('parametros', 'tipos-leche', 'modulos', 'reportes-widgets').
 */
function cambiarSubTabConfiguracion(subTabKey) {
    const tabs = ['parametros', 'tipos-leche', 'modulos', 'reportes-widgets', 'reportes'];
    tabs.forEach(t => {
        const btnPascal = document.getElementById(`btnSubTab${t === 'tipos-leche' ? 'TiposLeche' : t === 'reportes-widgets' ? 'ReportesWidgets' : t.charAt(0).toUpperCase() + t.slice(1)}`);
        const btnKebab = document.getElementById(`btnSubTabConfig-${t}`);
        const pane = document.getElementById(`subtab-config-${t}`);
        if (btnPascal) { btnPascal.classList.remove('active'); }
        if (btnKebab) {
            btnKebab.classList.remove('active');
            btnKebab.style.borderColor = '#cbd5e1';
            btnKebab.style.color = '#64748b';
            btnKebab.style.background = '#ffffff';
        }
        if (pane) pane.style.display = 'none';
    });

    const activeBtnPascal = document.getElementById(`btnSubTab${subTabKey === 'tipos-leche' ? 'TiposLeche' : subTabKey === 'reportes-widgets' ? 'ReportesWidgets' : subTabKey.charAt(0).toUpperCase() + subTabKey.slice(1)}`);
    const activeBtnKebab = document.getElementById(`btnSubTabConfig-${subTabKey}`);
    const activePane = document.getElementById(`subtab-config-${subTabKey}`);

    if (activeBtnPascal) activeBtnPascal.classList.add('active');
    if (activeBtnKebab) {
        activeBtnKebab.classList.add('active');
        activeBtnKebab.style.borderColor = '#6366f1';
        activeBtnKebab.style.color = '#4338ca';
        activeBtnKebab.style.background = '#e0e7ff';
    }
    if (activePane) activePane.style.display = 'block';

    const btnParam = document.getElementById('btnNuevoParametroGlobal');
    const btnTipo = document.getElementById('btnNuevoTipoLecheGlobal');
    if (btnParam) btnParam.style.display = (subTabKey === 'parametros') ? 'inline-flex' : 'none';
    if (btnTipo) btnTipo.style.display = (subTabKey === 'tipos-leche') ? 'inline-flex' : 'none';
}
window.cambiarSubTabConfiguracion = cambiarSubTabConfiguracion;

/**
 * Inicializa y recarga todos los catálogos y parámetros del módulo de Configuración.
 * 
 * Qué hace esta función:
 * 1. Activa por defecto la pestaña de Parámetros Globales.
 * 2. Ejecuta en paralelo las peticiones para cargar parámetros, tipos de leche, menús y widgets.
 * 
 * @param {boolean} [forceRefresh=false] - Si es true, ignora el caché en memoria y solicita datos frescos al backend.
 */
async function cargarModuloConfiguracionSistema(forceRefresh = false) {
    cambiarSubTabConfiguracion('parametros');
    await Promise.all([
        cargarParametrosSistema(forceRefresh),
        cargarTiposLeche(forceRefresh),
        cargarModulosMenuAdmin(forceRefresh),
        cargarReportesYWidgetsConfig(forceRefresh)
    ]);
}
window.cargarModuloConfiguracionSistema = cargarModuloConfiguracionSistema;

// --------------------------------------------------------------------------
// 1. PARÁMETROS GLOBALES DEL SISTEMA (TB_PARAMETROS_SISTEMA)
// --------------------------------------------------------------------------

/**
 * Consulta la lista de parámetros configurables desde el backend.
 * 
 * Qué hace esta función:
 * 1. Muestra un spinner de carga en `#tbodyParametrosSistema`.
 * 2. Realiza la petición GET autenticada a `/api/configuracion/parametros`.
 * 3. Almacena el resultado en `window.parametrosSistemaDataCache`.
 * 4. Invoca a `renderTablaParametrosSistema` para plasmar los datos en el DOM.
 * 
 * @param {boolean} [forceRefresh=false] - Forzar petición HTTP omitiendo caché local.
 */
async function cargarParametrosSistema(forceRefresh = false) {
    const tbody = document.getElementById('tbodyParametrosSistema');
    if (!tbody) return;

    if (!forceRefresh && window.parametrosSistemaDataCache && window.parametrosSistemaDataCache.length > 0) {
        renderTablaParametrosSistema(window.parametrosSistemaDataCache);
        return;
    }

    renderTableLoading('tbodyParametrosSistema', 6, 'Cargando parámetros globales...');

    const res = await apiFetch('/configuracion/parametros');
    if (res.ok && Array.isArray(res.data)) {
        window.parametrosSistemaDataCache = res.data;
        renderTablaParametrosSistema(window.parametrosSistemaDataCache);
    } else {
        renderTableError('tbodyParametrosSistema', 6, res.error || 'Error al cargar los parámetros del sistema.');
    }
}
window.cargarParametrosSistema = cargarParametrosSistema;

/**
 * Genera el HTML de las filas de parámetros del sistema con diseño moderno.
 * 
 * Qué hace esta función:
 * 1. Verifica si la lista contiene elementos; si está vacía, muestra un mensaje amigable.
 * 2. Asigna insignias de color distintivas para cada categoría (Finanzas, Liquidaciones, Rutas, General).
 * 3. Renderiza botones para editar y eliminar cada parámetro.
 * 
 * @param {Array<Object>} lista - Colección de objetos de parámetro obtenidos del backend.
 */
function renderTablaParametrosSistema(lista) {
    const tbody = document.getElementById('tbodyParametrosSistema');
    if (!tbody) return;

    if (!lista || lista.length === 0) {
        renderTableEmpty('tbodyParametrosSistema', 6, 'No se encontraron parámetros registrados.');
        return;
    }

    const catColors = {
        'FINANZAS': { bg: '#ecfdf5', text: '#059669', icon: 'fa-dollar-sign' },
        'LIQUIDACIONES': { bg: '#eff6ff', text: '#2563eb', icon: 'fa-file-invoice-dollar' },
        'RUTAS': { bg: '#fef3c7', text: '#d97706', icon: 'fa-truck' },
        'GENERAL': { bg: '#f3e8ff', text: '#7c3aed', icon: 'fa-gear' }
    };

    tbody.innerHTML = lista.map(p => {
        const cat = catColors[p.categoria] || { bg: '#f1f5f9', text: '#475569', icon: 'fa-tag' };
        return `
            <tr style="border-bottom: 1px solid #f1f5f9; transition: background 0.15s ease;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='transparent'">
                <td style="padding: 12px 16px;">
                    <div style="display: flex; align-items: center; gap: 8px;">
                        <span style="font-family: monospace; font-size: 12.5px; font-weight: 800; color: #1e1b4b; background: #e0e7ff; padding: 4px 8px; border-radius: 6px; letter-spacing: 0.5px;">
                            ${escapeHtml(p.clave)}
                        </span>
                    </div>
                </td>
                <td style="padding: 12px 16px;">
                    <span style="font-family: monospace; font-size: 13px; font-weight: 700; color: #0f172a; background: #f8fafc; border: 1px solid #e2e8f0; padding: 4px 10px; border-radius: 6px; display: inline-block; max-width: 260px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                        ${escapeHtml(p.valor || '')}
                    </span>
                </td>
                <td style="padding: 12px 16px; text-align: center;">
                    <span style="background: ${cat.bg}; color: ${cat.text}; font-size: 11.5px; font-weight: 800; padding: 4px 10px; border-radius: 999px; display: inline-flex; align-items: center; gap: 5px;">
                        <i class="fa-solid ${cat.icon}"></i> ${escapeHtml(p.categoria)}
                    </span>
                </td>
                <td style="padding: 12px 16px; text-align: center;">
                    <span style="background: #f1f5f9; color: #475569; font-size: 11px; font-weight: 700; padding: 3px 8px; border-radius: 6px; text-transform: uppercase;">
                        ${escapeHtml(p.tipoDato || 'STRING')}
                    </span>
                </td>
                <td style="padding: 12px 16px; font-size: 12.5px; color: #475569;">
                    ${escapeHtml(p.descripcion || '-')}
                </td>
                <td style="padding: 12px 16px; text-align: center;">
                    <div style="display: inline-flex; gap: 6px;">
                        <button type="button" class="btn btn-outline" style="padding: 6px 10px; font-size: 12px; color: #7c3aed; border-color: #ddd6fe;" onclick="abrirModalParametroSistema('${escapeHtml(p.clave)}')" title="Editar Parámetro">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button type="button" class="btn btn-outline" style="padding: 6px 10px; font-size: 12px; color: #dc2626; border-color: #fecaca;" onclick="eliminarParametroSistema('${escapeHtml(p.clave)}')" title="Eliminar Parámetro">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

/**
 * Filtra reactivamente la tabla de parámetros en base a la categoría seleccionada y la caja de búsqueda.
 */
function filtrarTablaParametrosSistema() {
    const cat = document.getElementById('filtroCategoriaParametros')?.value || '';
    const q = (document.getElementById('buscadorParametrosSistema')?.value || '').toLowerCase().trim();

    let filtrados = window.parametrosSistemaDataCache || [];
    if (cat) {
        filtrados = filtrados.filter(p => p.categoria === cat);
    }
    if (q) {
        filtrados = filtrados.filter(p => 
            (p.clave && p.clave.toLowerCase().includes(q)) ||
            (p.valor && p.valor.toLowerCase().includes(q)) ||
            (p.descripcion && p.descripcion.toLowerCase().includes(q))
        );
    }
    renderTablaParametrosSistema(filtrados);
}
window.filtrarTablaParametrosSistema = filtrarTablaParametrosSistema;

/**
 * Abre el modal de creación o edición de un Parámetro del Sistema.
 * 
 * @param {string|null} [clave=null] - Clave del parámetro a editar, o null para crear uno nuevo.
 */
function abrirModalParametroSistema(clave = null) {
    const titulo = document.getElementById('modalParametroTitulo');
    const inputClave = document.getElementById('paramClave');
    const selectCat = document.getElementById('paramCategoria');
    const selectTipo = document.getElementById('paramTipoDato');
    const textValor = document.getElementById('paramValor');
    const inputDesc = document.getElementById('paramDescripcion');

    if (clave) {
        const item = (window.parametrosSistemaDataCache || []).find(p => p.clave === clave);
        if (titulo) titulo.textContent = `Editar Parámetro: ${clave}`;
        if (inputClave) { inputClave.value = item?.clave || clave; inputClave.readOnly = true; inputClave.style.background = '#f1f5f9'; }
        if (selectCat) selectCat.value = item?.categoria || 'GENERAL';
        if (selectTipo) selectTipo.value = item?.tipoDato || 'STRING';
        if (textValor) textValor.value = item?.valor || '';
        if (inputDesc) inputDesc.value = item?.descripcion || '';
    } else {
        if (titulo) titulo.textContent = 'Nuevo Parámetro del Sistema';
        if (inputClave) { inputClave.value = ''; inputClave.readOnly = false; inputClave.style.background = '#ffffff'; }
        if (selectCat) selectCat.value = 'FINANZAS';
        if (selectTipo) selectTipo.value = 'STRING';
        if (textValor) textValor.value = '';
        if (inputDesc) inputDesc.value = '';
    }

    abrirModalCustom('modalParametroSistema');
}
window.abrirModalParametroSistema = abrirModalParametroSistema;

/**
 * Procesa el envío del formulario para crear o actualizar un Parámetro del Sistema.
 * 
 * @param {Event} event - Evento del formulario submit.
 */
async function guardarParametroSistemaForm(event) {
    event.preventDefault();
    const clave = document.getElementById('paramClave')?.value?.trim().toUpperCase();
    const categoria = document.getElementById('paramCategoria')?.value;
    const tipoDato = document.getElementById('paramTipoDato')?.value;
    const valor = document.getElementById('paramValor')?.value?.trim();
    const descripcion = document.getElementById('paramDescripcion')?.value?.trim();

    if (!clave || valor === undefined) {
        Swal.fire({ icon: 'warning', title: 'Campos requeridos', text: 'Debe especificar la clave y el valor del parámetro.' });
        return;
    }

    const payload = { clave, categoria, tipoDato, valor, descripcion };
    const res = await apiFetch(`/configuracion/parametros/${encodeURIComponent(clave)}`, {
        method: 'PUT',
        body: payload
    });

    if (res.ok) {
        cerrarModalCustom('modalParametroSistema');
        Swal.fire({
            icon: 'success',
            title: '¡Parámetro Guardado!',
            text: `El parámetro ${clave} se configuró exitosamente.`,
            timer: 1800,
            showConfirmButton: false
        });
        await cargarParametrosSistema(true);
    } else {
        Swal.fire({ icon: 'error', title: 'Error al Guardar', text: res.error || 'No se pudo guardar el parámetro.' });
    }
}
window.guardarParametroSistemaForm = guardarParametroSistemaForm;

/**
 * Elimina un parámetro de configuración del sistema tras confirmación del usuario.
 * 
 * @param {string} clave - Clave identificadora única del parámetro.
 */
async function eliminarParametroSistema(clave) {
    const confirm = await Swal.fire({
        title: `¿Eliminar parámetro ${clave}?`,
        text: 'Esta acción removerá esta variable de configuración del sistema.',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#dc2626',
        cancelButtonColor: '#64748b',
        confirmButtonText: 'Sí, eliminar',
        cancelButtonText: 'Cancelar'
    });

    if (!confirm.isConfirmed) return;

    const res = await apiFetch(`/configuracion/parametros/${encodeURIComponent(clave)}`, {
        method: 'DELETE'
    });

    if (res.ok) {
        Swal.fire({ icon: 'success', title: 'Eliminado', text: `El parámetro ${clave} fue eliminado.`, timer: 1500, showConfirmButton: false });
        await cargarParametrosSistema(true);
    } else {
        Swal.fire({ icon: 'error', title: 'Error al eliminar', text: res.error || 'No se pudo eliminar el parámetro.' });
    }
}
window.eliminarParametroSistema = eliminarParametroSistema;

